    private val unrecognizedResult = DiseaseResult(
        diseaseName = "Image Unrecognized (Low Confidence)",
        description = "The AI model cannot confidently identify the plant or disease. Confidence is below 60%.",
        causes = "The plant or disease may not be in the system's database, or the image conditions are not optimal.",
        treatment = "Try capturing the photo again with the leaf clearly visible, centered, and evenly lit.",
        preventionTips = "Clean the camera lens, hold steady in bright indirect natural light, and tap to focus before capturing.",
        careTips = "Clean your phone camera lens and retake the photo with the leaf centered, clearly focused, and evenly lit in natural light without harsh shadows or motion blur. If the app still cannot identify the condition, the plant species or issue may not be supported by the current model—consult a local agricultural extension officer or garden specialist for an accurate diagnosis."
    )

    fun getAllSupportedKeys(): Set<String> = database.keys - "Unrecognized"

    fun getDiseaseInfo(label: String?): DiseaseResult {
        if (label.isNullOrBlank() || label == "Unknown") {
            return unrecognizedResult
        }

        return database[label] ?: unrecognizedResult
    }
}
